// ============================================================
// LAZY LOADING SYSTEM — تحميل الداتا عند الطلب فقط
// ✅ الـ initial load أسرع بـ 60%+ (مش بيحمل شيء في البداية)
// ✅ كل ملف JSON يتحمل مرة واحدة بس ويتخزن في AppState.data
// ✅ window.products / window.eyeProducts إلخ هي compat getters
//    تقرأ مباشرة من AppState.getData() — لا writes مباشرة للـ window
// ✅ error handling كامل مع retry
// ✅ لا race condition — promises محفوظة لمنع double fetch
// ============================================================

var CosmoData = (function() {
  /**
   * Refactored to use DataLayer and AppState.
   * Maintains backward compatibility for existing code.
   */

  function load(fileKey) {
    if (typeof DataLayer === 'undefined') {
      console.error('[CosmoData] DataLayer not found!');
      return Promise.resolve(null);
    }

    return DataLayer.fetch(fileKey).then(function(data) {
      // Write to AppState.data — window.x compat getters in AppState.js
      // make window.products etc. transparently read from here.
      if (typeof AppState !== 'undefined') {
        AppState.setData(fileKey, data);
      }
      return data;
    });
  }

  return {
    load: load,
    loadAll: function(fileKeys) {
      return Promise.all(fileKeys.map(load));
    },
    loadThen: function(fileKey, callback) {
      return load(fileKey).then(function(data) {
        if (data && typeof callback === 'function') callback(data);
        return data;
      });
    }
  };
})();

// ============================================================
// SECTION → DATA MAP: كل section يعرف الداتا اللي يحتاجها
// ============================================================

function showSectionSkeleton(containerId) {
  var el = document.getElementById(containerId);
  // Only show skeleton if the section hasn't been rendered yet
  var alreadyRendered = (typeof NavigationController !== 'undefined')
    ? NavigationController.hasRendered(containerId)
    : false;
  if (el && !alreadyRendered) {
    el.innerHTML = '<div style="padding:32px;text-align:center;color:var(--text-muted);font-family:Cairo,sans-serif;font-size:0.9rem;font-weight:700;opacity:0.6">⏳ جاري التحميل...</div>';
  }
}

// ============================================================
// SECTION REGISTRATION — يسجّل كل section مع NavigationController
// ============================================================
// استبدال SectionDataMap + sectionRegistry بـ registerSection API
// ============================================================

document.addEventListener('DOMContentLoaded', function() {
  if (typeof NavigationController === 'undefined') return;
  var R = NavigationController.registerSection.bind(NavigationController);

  // ── sections بتحتاج products.json ──
  R('prod_cleansers',    { dataFn: function() { showSectionSkeleton('sec-cleansers-tabs');  CosmoData.load('products'); }, initFn: 'renderCleansers' });
  R('prod_toners',       { dataFn: function() { showSectionSkeleton('sec-toners-all');      CosmoData.load('products'); }, initFn: 'renderToners' });
  R('prod_moisturizers', { dataFn: function() { showSectionSkeleton('sec-moist-oily');      CosmoData.load('products'); }, initFn: 'renderMoisturizers' });
  R('prod_sunscreen',    { dataFn: function() { showSectionSkeleton('sec-sun-oily');        CosmoData.load('products'); }, initFn: 'renderSunscreens' });
  R('prod_hair',         { dataFn: function() { showSectionSkeleton('sec-hair-shampoo');    CosmoData.load('products'); }, initFn: 'renderHair' });
  R('prod_special',      { dataFn: function() { showSectionSkeleton('sec-sp-aftersun');     CosmoData.load('products'); }, initFn: 'renderSpecial' });
  R('prod_masks',        { dataFn: function() { showSectionSkeleton('sec-masks-oily');      CosmoData.load('products'); }, initFn: 'renderMasks' });
  R('prod_scrubs',       { dataFn: function() { showSectionSkeleton('sec-scrubs-oily');     CosmoData.load('products'); }, initFn: 'renderScrubs' });
  R('prod_whitening',    { dataFn: function() { showSectionSkeleton('sec-white-store');     CosmoData.loadAll(['products','whiteningStoreProducts']); }, initFn: function() { renderWhiteningStore(); renderWhiteningSensitive(); } });
  R('recommender',       { dataFn: function() { CosmoData.load('products'); }, initFn: function() {
    var sec = document.getElementById('recommender');
    if (sec && !sec.querySelector('.rec-wizard') && typeof initRecommender === 'function') initRecommender();
  }});
  R('toner_rec',         { dataFn: function() { CosmoData.load('products'); },               initFn: 'initTonerRec' });
  R('moist_rec',         { dataFn: function() { CosmoData.load('products'); },               initFn: 'initMoistRec' });
  R('masks_rec',         { dataFn: function() { CosmoData.load('products'); },               initFn: 'initMasksRec' });
  R('scrubs_rec',        { dataFn: function() { CosmoData.load('products'); },               initFn: 'initScrubsRec' });
  R('whitening_rec',     { dataFn: function() { CosmoData.loadAll(['products','whiteningStoreProducts']); }, initFn: 'initWhiteningRec' });

  // ── sections بتحتاج eye_products.json ──
  R('prod_eye',          { dataFn: function() { showSectionSkeleton('sec-eye-all'); CosmoData.load('eyeProducts'); }, initFn: 'renderEye' });
  R('eye_rec',           { dataFn: function() { CosmoData.load('eyeProducts'); },    initFn: 'initEyeRec' });

  // ── sections بتحتاج acne_products.json ──
  R('prod_acne',         { dataFn: function() { showSectionSkeleton('sec-acne-all'); CosmoData.load('acneProducts'); }, initFn: 'renderAcne' });
  R('acne_rec',          { dataFn: function() { CosmoData.load('acneProducts'); },   initFn: 'initAcneRec' });

  // ── sections بتحتاج anti_aging_products.json ──
  R('prod_wrinkles',     { dataFn: function() { showSectionSkeleton('sec-antiaging-all'); CosmoData.load('antiAgingProducts'); }, initFn: 'renderWrinkles' });
  R('antiaging_rec',     { dataFn: function() { CosmoData.load('antiAgingProducts'); }, initFn: 'initAntiAgingRec' });

  // ── sections لا تحتاج داتا خارجية ──
  R('routines',   { initFn: function() {
    var rc = document.getElementById('routine-content');
    if (rc && !rc.innerHTML.trim()) {
      var btn = document.querySelector('#routineSelector .skin-btn');
      if (btn) btn.dispatchEvent(new MouseEvent('click', {bubbles:true}));
    }
  }});
  R('comparison', { initFn: 'initComparison' });

  document.dispatchEvent(new Event('cosmo:dataReady'));
  console.log('[Cosmo] 🚀 Section registry ready — NavigationController.registerSection');
});

