function makePriceCard(p) {
  const desc = p.desc || p.note || '';
  const price = typeof p.price === 'number' ? p.price.toLocaleString('ar-EG') : p.price;
  return `
    <div class="store-card">
      <div class="store-card-name">${p.name}</div>
      ${p.code ? `<div class="store-card-code">كود المنتج: <span>${p.code}</span></div>` : ''}
      ${desc ? `<div class="store-card-desc">${desc}</div>` : ''}
      <div class="store-card-price">${price} جنيه</div>
    </div>`;
}

function makeProdGrid(products, emptyMsg='لا توجد منتجات في هذه الفئة') {
  if (!products || products.length === 0) return `<div class="info-note">${emptyMsg}</div>`;
  return `<div class="store-cards-grid">${products.map(p => makePriceCard(p)).join('')}</div>`;
}

function renderCleansers() {
  var _el = document.getElementById('sec-cleansers-tabs');
  if (!_el) return;
  if (typeof NavigationController !== 'undefined' && NavigationController.hasRendered('sec-cleansers-tabs')) return;
  if (typeof NavigationController !== 'undefined') NavigationController.markRendered('sec-cleansers-tabs');
  const container = _el;

  // Build all categorized lists from products + skinMap
  const cats = storeData;
  const all = [...cats.gels, ...cats.micellar, ...cats.soaps, ...cats.offers];

  // Group by primary skin type
  const groups = { oily:[], dry:[], sensitive:[], whitening:[], normal:[] };
  all.forEach(p => {
    const skins = getProductSkinTypes(p.name);
    const primary = skins[0] === 'mixed' ? 'oily' : skins[0];
    if (groups[primary]) groups[primary].push(p);
  });

  // Also group by product type
  const byType = {
    gels: cats.gels,
    micellar: cats.micellar,
    soaps: cats.soaps,
    offers: cats.offers,
  };

  const skinColors = { oily:'#4a90d9', dry:'#e07a30', sensitive:'#e8446a', whitening:'#9c5fd4', normal:'#4caf7d' };
  const skinIcons  = { oily:'💧', dry:'🌵', sensitive:'🌸', whitening:'✨', normal:'😊' };
  const skinNames  = { oily:'البشرة الدهنية / المختلطة', dry:'البشرة الجافة', sensitive:'البشرة الحساسة', whitening:'التفتيح', normal:'البشرة العادية' };

  const tabs = [
    { key:'by_skin',    label:'🎯 حسب نوع البشرة', color:'var(--rose)' },
    { key:'oily',       label:`${skinIcons.oily} دهنية / مختلطة (${groups.oily.length})`,       color: skinColors.oily },
    { key:'dry',        label:`${skinIcons.dry} جافة (${groups.dry.length})`,           color: skinColors.dry },
    { key:'sensitive',  label:`${skinIcons.sensitive} حساسة (${groups.sensitive.length})`, color: skinColors.sensitive },
    { key:'whitening',  label:`${skinIcons.whitening} تفتيح (${groups.whitening.length})`, color: skinColors.whitening },
    { key:'normal',     label:`${skinIcons.normal} عادية (${groups.normal.length})`,    color: skinColors.normal },
    { key:'gels',       label:`🧴 غسولات وفوم (${cats.gels.length})`,                  color:'var(--rose)' },
    { key:'micellar',   label:`💧 ميسيلار (${cats.micellar.length})`,                  color:'#4a90d9' },
    { key:'soaps',      label:`🫧 صوابين (${cats.soaps.length})`,                      color:'#4caf7d' },
    { key:'offers',     label:`🎁 عروض (${cats.offers.length})`,                       color:'var(--gold)' },
  ];

  const totalAll = all.length;

  container.innerHTML = `
    <div style="background:linear-gradient(135deg,#fde8ee,#fff8f2);border:2px solid var(--rose-light);border-radius:14px;padding:14px 18px;margin-bottom:18px;display:flex;align-items:center;gap:12px">
      <span style="font-size:1.8rem">🏪</span>
      <div>
        <div style="font-weight:800;font-size:1rem;color:var(--dark)">آل عبد اللطيف الطرشوبي — منتجات التنظيف</div>
        <div style="font-size:0.8rem;color:var(--text-muted)">إجمالي ${totalAll} منتج — اختار التقسيمة المناسبة</div>
      </div>
    </div>
    <input id="cleanserSearch" type="text" placeholder="🔍 ابحث باسم المنتج أو الكود..." oninput="searchCleansers()" style="width:100%;padding:11px 16px;border:2px solid var(--border);border-radius:var(--radius-sm);font-family:Cairo,sans-serif;font-size:0.92rem;outline:none;box-sizing:border-box;margin-bottom:14px">
    <div id="cleanserSearchResult"></div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:18px" id="cleanserTabsMain">
      ${tabs.map((t,i) => `
        <button onclick="switchMainCleanserTab('${t.key}',this)"
          style="padding:7px 14px;border-radius:30px;border:2px solid ${i===0?t.color:'var(--border)'};background:${i===0?t.color:'white'};color:${i===0?'white':'var(--text-muted)'};font-family:Cairo,sans-serif;font-size:0.78rem;font-weight:700;cursor:pointer;transition:all 0.2s">
          ${t.label}
        </button>`).join('')}
    </div>
    <div id="cleanserMainContent"></div>
  `;

  // Store derived cleanser data in AppState (replaces window._cleanserData)
  if (typeof AppState !== 'undefined') {
    AppState.setState('ui.cleanser', { groups, byType, skinColors, skinIcons, skinNames, tabs });
  }

  // Render first tab (by_skin overview)
  renderCleanserBySkin();
}

function switchMainCleanserTab(key, btn) {
  // Update button styles
  const allBtns = document.querySelectorAll('#cleanserTabsMain button');
  const d = (typeof AppState !== 'undefined') ? AppState.getState('ui.cleanser') : null;
  if (!d) return;
  allBtns.forEach((b, i) => {
    const t = d.tabs[i];
    b.style.background = 'white';
    b.style.color = 'var(--text-muted)';
    b.style.borderColor = 'var(--border)';
  });
  const matchTab = d.tabs.find(t => t.key === key);
  btn.style.background = matchTab ? matchTab.color : 'var(--rose)';
  btn.style.color = 'white';
  btn.style.borderColor = matchTab ? matchTab.color : 'var(--rose)';

  const content = document.getElementById('cleanserMainContent');
  const { groups, byType, skinColors, skinIcons, skinNames } = d;

  if (key === 'by_skin') {
    renderCleanserBySkin();
  } else if (['oily','dry','sensitive','whitening','normal'].includes(key)) {
    const sorted = [...(groups[key]||[])].sort((a,b) => a.price - b.price);
    content.innerHTML = sorted.length
      ? `<div class="store-cards-grid">${sorted.map(p => makePriceCard(p)).join('')}</div>`
      : `<div class="info-note">لا توجد منتجات في هذه الفئة</div>`;
  } else {
    const map = { gels:'gels', micellar:'micellar', soaps:'soaps', offers:'offers' };
    const sorted = [...(byType[map[key]]||[])].sort((a,b) => a.price - b.price);
    content.innerHTML = sorted.length
      ? `<div class="store-cards-grid">${sorted.map(p => makePriceCard(p)).join('')}</div>`
      : `<div class="info-note">لا توجد منتجات</div>`;
  }
}

function renderCleanserBySkin() {
  const d = (typeof AppState !== 'undefined') ? AppState.getState('ui.cleanser') : null;
  if (!d) return;
  const { groups, skinColors, skinIcons, skinNames } = d;
  const content = document.getElementById('cleanserMainContent');

  const skinOrder = ['oily','dry','sensitive','whitening','normal'];
  content.innerHTML = skinOrder.map(skin => {
    const items = [...(groups[skin]||[])].sort((a,b) => a.price - b.price);
    if (!items.length) return '';
    return `
      <div style="margin-bottom:28px">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;padding-right:14px;border-right:4px solid ${skinColors[skin]}">
          <span style="font-size:1.3rem">${skinIcons[skin]}</span>
          <div>
            <div style="font-size:1rem;font-weight:800;color:var(--dark)">${skinNames[skin]}</div>
            <div style="font-size:0.75rem;color:var(--text-muted)">${items.length} منتج — من ${Math.min(...items.map(p=>p.price))} إلى ${Math.max(...items.map(p=>p.price))} جنيه</div>
          </div>
        </div>
        <div class="store-cards-grid">${items.map(p => makePriceCard(p)).join('')}</div>
      </div>`;
  }).join('');
}

