function showRoutine(type) {
  document.querySelectorAll('#routineSelector .skin-btn').forEach(b => b.classList.remove('active'));
  event.target.classList.add('active');
  const r = routines[type];
  const c = r.color;

  const prodCards = arr => arr.map(p => `
    <div style="background:#faf7f9;border-radius:10px;padding:12px 14px;border:1px solid var(--border)">
      <div style="font-size:0.68rem;font-weight:800;color:${c};text-transform:uppercase;letter-spacing:1px;margin-bottom:3px">${p.brand}</div>
      <div style="font-size:0.88rem;font-weight:700;color:var(--dark);margin-bottom:4px;line-height:1.3">${p.name}</div>
      <div style="font-size:0.78rem;color:var(--text-muted);line-height:1.5;margin-bottom:8px">${p.desc}</div>
      <a href="https://alabdellatif-tarshouby.com/ar" target="_blank"
        style="display:inline-flex;align-items:center;gap:4px;background:${c};color:white;padding:4px 12px;border-radius:20px;font-size:0.72rem;font-weight:700;text-decoration:none;transition:opacity 0.2s"
        onmouseover="this.style.opacity='.8'" onmouseout="this.style.opacity='1'">🛒 تسوّق</a>
    </div>`).join('');

  const stepHTML = steps => steps.map(s => `
    <div style="background:white;border-radius:14px;padding:16px 18px;box-shadow:var(--shadow);margin-bottom:12px;border-right:4px solid ${c}">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">
        <div style="background:${c};color:white;min-width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.78rem;font-weight:800">${s.step}</div>
        <div style="font-size:0.95rem;font-weight:800;color:var(--dark)">${s.icon} ${s.title}</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px">${prodCards(s.products)}</div>
    </div>`).join('');

  const weeklyHTML = r.weekly?.length ? `
    <div style="background:white;border-radius:14px;padding:16px 18px;box-shadow:var(--shadow);border-right:4px solid var(--gold);margin-top:4px">
      <div style="font-size:0.95rem;font-weight:800;color:var(--dark);margin-bottom:12px">🗓️ أسبوعياً</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px">
        ${r.weekly.map(p => `
          <div style="background:#fdf6ee;border-radius:10px;padding:12px 14px;border:1px solid #f0d8c0">
            <div style="font-size:0.68rem;font-weight:800;color:var(--gold);text-transform:uppercase;letter-spacing:1px;margin-bottom:3px">${p.brand}</div>
            <div style="font-size:0.88rem;font-weight:700;color:var(--dark);margin-bottom:4px">${p.name}</div>
            <div style="font-size:0.78rem;color:var(--text-muted);line-height:1.5;margin-bottom:8px">${p.desc}</div>
            <a href="https://alabdellatif-tarshouby.com/ar" target="_blank"
              style="display:inline-flex;align-items:center;gap:4px;background:var(--gold);color:white;padding:4px 12px;border-radius:20px;font-size:0.72rem;font-weight:700;text-decoration:none">🛒 تسوّق</a>
          </div>`).join('')}
      </div>
    </div>` : '';

  document.getElementById('routine-content').innerHTML = `
    <div style="background:linear-gradient(135deg,${c}22,${c}08);border:2px solid ${c}44;border-radius:16px;padding:14px 20px;margin-bottom:20px;display:flex;align-items:center;gap:12px">
      <div style="font-size:2rem">${r.label.split(' ')[0]}</div>
      <div>
        <div style="font-size:1.1rem;font-weight:900;color:var(--dark)">${r.label}</div>
        <div style="font-size:0.8rem;color:var(--text-muted)">روتين كامل صباحاً ومساءً وأسبوعياً</div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:16px">
      <div>
        <div style="background:linear-gradient(135deg,#fff9e6,#fff3cc);border-radius:12px;padding:10px 16px;margin-bottom:14px;font-size:0.88rem;font-weight:800;color:#8a6000">☀️ الروتين الصباحي</div>
        ${stepHTML(r.morning)}
      </div>
      <div>
        <div style="background:linear-gradient(135deg,#1a0a1215,#1a0a120a);border-radius:12px;padding:10px 16px;margin-bottom:14px;font-size:0.88rem;font-weight:800;color:var(--dark)">🌙 الروتين المسائي</div>
        ${stepHTML(r.evening)}
      </div>
    </div>
    ${weeklyHTML}
    <div style="background:#f0faf5;border-radius:12px;padding:12px 16px;border-right:3px solid #27ae60;font-size:0.8rem;color:#1a6a3a;margin-top:14px;line-height:1.7">
      💡 <strong>ملاحظة:</strong> اضغط "تسوّق" لأي منتج للبحث عنه مباشرةً على موقع آل عبد اللطيف الطرشوبي.
    </div>`;
}
